mod io;
use quantum_ecc::circuit::{Op,OperationType as K,QubitId,BitId};
use std::collections::{HashMap,HashSet,BTreeSet};
use sha3::{Digest,Sha3_256};
type E=u32;
// Exact semantic keys for small classical Boolean supports. Large functions
// remain opaque symbols of their actual immutable expressions; no sampling.
#[derive(Clone,Debug,PartialEq,Eq,Hash)]struct SemTruth{atoms:Vec<u32>,table:u64}
impl SemTruth{
 fn mask(n:usize)->u64{if n==6{u64::MAX}else{(1u64<<(1usize<<n))-1}}
 fn complement(&self)->Self{Self{atoms:self.atoms.clone(),table:self.table^Self::mask(self.atoms.len())}}
 fn shrink(mut self)->Self{let mut bit=0;while bit<self.atoms.len(){let n=self.atoms.len();let step=1usize<<bit;let independent=(0..1usize<<n).filter(|r|r&step==0).all(|r|(self.table>>r)&1==(self.table>>(r|step))&1);if independent{let mut out=0u64;for row in 0..1usize<<(n-1){let old=(row&(step-1))|((row&!(step-1))<<1);out|=((self.table>>old)&1)<<row;}self.atoms.remove(bit);self.table=out;}else{bit+=1;}}self}
 fn key(&self)->(Self,u32){let neg=(self.table&1)as u32;if neg==0{(self.clone(),0)}else{(self.complement(),1)}}
}
impl Expr{
 fn semantic(&self,v:u32)->SemTruth{if v<=1{return SemTruth{atoms:vec![],table:v as u64};}let t=&self.truths[(v/2-1)as usize];if v&1==0{t.clone()}else{t.complement()}}
 fn combine_semantic(&self,k:u8,a:u32,b:u32)->Option<SemTruth>{let a=self.semantic(a);let b=self.semantic(b);let mut atoms=a.atoms.clone();atoms.extend_from_slice(&b.atoms);atoms.sort_unstable();atoms.dedup();if atoms.len()>6{return None;}let ap:Vec<_>=a.atoms.iter().map(|v|atoms.binary_search(v).unwrap()).collect();let bp:Vec<_>=b.atoms.iter().map(|v|atoms.binary_search(v).unwrap()).collect();let project=|row:usize,positions:&[usize]|positions.iter().enumerate().fold(0usize,|v,(i,&bit)|v|(((row>>bit)&1)<<i));let mut table=0;for row in 0..1usize<<atoms.len(){let av=(a.table>>project(row,&ap))&1;let bv=(b.table>>project(row,&bp))&1;table|=(if k==1{av&bv}else{av^bv})<<row;}Some(SemTruth{atoms,table}.shrink())}
 fn semantic_node(&mut self,k:u8,a:u32,b:u32)->u32{let summary=self.combine_semantic(k,a,b);if let Some(t)=&summary{if t.atoms.is_empty(){return(t.table&1)as u32;}let(key,neg)=t.key();if let Some(&v)=self.canonical.get(&key){return v^neg;}}let id=self.atom();*self.nodes.last_mut().unwrap()=(k,a,b);if let Some(t)=summary{let(key,neg)=t.key();*self.truths.last_mut().unwrap()=t;self.canonical.insert(key,id^neg);}id}
}

#[derive(Default)]struct Expr{restricting:bool,truths:Vec<SemTruth>,canonical:HashMap<SemTruth,u32>,nodes:Vec<(u8,u32,u32)>,implications:HashMap<(u32,u32),bool>,next:u32,and:HashMap<(u32,u32),u32>,xor:HashMap<(u32,u32),u32>}
impl Expr{
 fn atom(&mut self)->u32{self.next+=2;self.nodes.push((0,0,0));let t=SemTruth{atoms:vec![self.next],table:2};self.truths.push(t.clone());self.canonical.insert(t,self.next);self.next}
 fn and(&mut self,mut a:u32,mut b:u32)->u32{if a==0||b==0{return 0;}if a==1{return b;}if b==1||a==b{return a;}if a==b^1{return 0;}if a>b{std::mem::swap(&mut a,&mut b);}if let Some(&v)=self.and.get(&(a,b)){return v;}if !self.restricting{self.restricting=true;let mut result=None;if let Some(v)=self.cofactor(b,a,6){if v!=b{result=Some(self.and(a,v));}}if result.is_none(){if let Some(v)=self.cofactor(a,b,6){if v!=a{result=Some(self.and(b,v));}}}self.restricting=false;if let Some(v)=result{self.and.insert((a,b),v);return v;}}let v=self.semantic_node(1,a,b);self.and.insert((a,b),v);v}
 fn or(&mut self,a:u32,b:u32)->u32{self.and(a^1,b^1)^1}
 fn xor(&mut self,mut a:u32,mut b:u32)->u32{if a==0{return b;}if b==0{return a;}if a==1{return b^1;}if b==1{return a^1;}if a==b{return 0;}if a==b^1{return 1;}let neg=(a^b)&1;a&=!1;b&=!1;if a>b{std::mem::swap(&mut a,&mut b);}if let Some(&v)=self.xor.get(&(a,b)){return v^neg;}let v=self.semantic_node(2,a,b);self.xor.insert((a,b),v);v^neg}
 fn ite(&mut self,g:u32,new:u32,old:u32)->u32{if g==0||new==old{return old;}if g==1{return new;}if old==0{return self.and(g,new);}if new==0{return self.and(g^1,old);}if old==1{return self.or(g^1,new);}if new==1{return self.or(g,old);}if new==old^1{return self.xor(g,old);}let a=self.and(g,new);let b=self.and(g^1,old);self.or(a,b)}
}
impl Expr{
 fn quick_implies(&self,a:u32,b:u32,depth:usize)->bool{if a==0||b==1||a==b{return true;}if depth==0||a<=1||b==0{return false;}let an=self.nodes[(a/2-1)as usize];if an.0==1{if a&1==0{if self.quick_implies(an.1,b,depth-1)||self.quick_implies(an.2,b,depth-1){return true;}}else if self.quick_implies(an.1^1,b,depth-1)&&self.quick_implies(an.2^1,b,depth-1){return true;}}let bn=self.nodes[(b/2-1)as usize];if bn.0==1{if b&1==0{return self.quick_implies(a,bn.1,depth-1)&&self.quick_implies(a,bn.2,depth-1);}return self.quick_implies(a,bn.1^1,depth-1)||self.quick_implies(a,bn.2^1,depth-1);}false}
 fn implies(&mut self,a:u32,b:u32)->bool{if self.quick_implies(a,b,12){return true;}if let Some(&v)=self.implications.get(&(a,b)){return v;}let root=self.and(a,b^1);let answer=self.zero_truth_table(root);self.implications.insert((a,b),answer);answer}
 fn zero_truth_table(&self,root:u32)->bool{if root<=1{return root==0;}let mut pending=vec![root&!1];let mut visited=BTreeSet::new();let mut atoms=BTreeSet::new();while let Some(id)=pending.pop(){if id<=1||!visited.insert(id){continue;}if visited.len()>4096{return false;}let(k,a,b)=self.nodes[(id/2-1)as usize];if k==0{atoms.insert(id);if atoms.len()>10{return false;}}else{pending.push(a&!1);pending.push(b&!1);}}
  let ord:HashMap<_,_>=atoms.into_iter().enumerate().map(|(i,v)|(v,i)).collect();let cases=1usize<<ord.len();let words=cases.div_ceil(64);let mut table:HashMap<u32,Vec<u64>>=HashMap::new();let get=|lit:u32,table:&HashMap<u32,Vec<u64>>,j:usize|if lit<=1{if lit==1{u64::MAX}else{0}}else{let v=table[&(lit&!1)][j];if lit&1!=0{!v}else{v}};
  for id in visited{let(k,a,b)=self.nodes[(id/2-1)as usize];let mut row=vec![0;words];if k==0{let shift=ord[&id];for assignment in 0..cases{row[assignment/64]|=(((assignment>>shift)&1)as u64)<<(assignment%64);}}else{for j in 0..words{let x=get(a,&table,j);let y=get(b,&table,j);row[j]=if k==1{x&y}else{x^y};}}table.insert(id,row);}
  let last_mask=if cases<64{(1u64<<cases)-1}else{u64::MAX};(0..words).all(|j|get(root,&table,j)&if j+1==words{last_mask}else{u64::MAX}==0)
 }
}
impl Expr{fn cofactor(&mut self,expression:u32,assumed:u32,depth:usize)->Option<u32>{if expression==assumed{return Some(1);}if expression==assumed^1{return Some(0);}if expression<=1||depth==0{return None;}let(k,a,b)=self.nodes[(expression/2-1)as usize];if k==0{return None;}let left=self.cofactor(a,assumed,depth-1);let right=self.cofactor(b,assumed,depth-1);if left.is_none()&&right.is_none(){return None;}let a=left.unwrap_or(a);let b=right.unwrap_or(b);let value=if k==1{self.and(a,b)}else{self.xor(a,b)};Some(value^(expression&1))}}

impl Expr{fn lookup_xor(&self,mut a:u32,mut b:u32)->Option<u32>{if a==0{return Some(b);}if b==0{return Some(a);}if a==1{return Some(b^1);}if b==1{return Some(a^1);}if a==b{return Some(0);}if a==b^1{return Some(1);}let neg=(a^b)&1;a&=!1;b&=!1;if a>b{std::mem::swap(&mut a,&mut b);}if let Some(&v)=self.xor.get(&(a,b)){return Some(v^neg);}let truth=self.combine_semantic(2,a,b)?;if truth.atoms.is_empty(){return Some((truth.table&1)as u32^neg);}let(key,complement)=truth.key();self.canonical.get(&key).map(|&v|v^complement^neg)}}
struct Algebra{inner:Expr}
impl Algebra{fn fresh(&mut self)->E{self.inner.atom()}fn and(&mut self,a:&E,b:&E)->E{self.inner.and(*a,*b)}fn xor(&mut self,a:&E,b:&E)->E{self.inner.xor(*a,*b)}fn select(&mut self,old:&E,new:&E,cond:&E)->E{self.inner.ite(*cond,*new,*old)}}
fn initial_inputs(ops:&[Op],nq:usize,nb:usize,alg:&mut Algebra)->(Vec<E>,Vec<E>){let no=u64::MAX;let(mut q,mut c)=(vec![0;nq],vec![0;nb]);let(mut qs,mut cs)=(HashSet::new(),HashSet::new());for o in ops{if o.kind==K::AppendToRegister{if o.q_target.0!=no&&qs.insert(o.q_target.0){q[o.q_target.0 as usize]=alg.fresh();}if o.c_target.0!=no&&cs.insert(o.c_target.0){c[o.c_target.0 as usize]=alg.fresh();}}}(q,c)}
fn hash(ops:&[Op])->String {
 let mut h=Sha3_256::new();for o in ops {h.update((o.kind as u64).to_le_bytes());
 for v in [o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]{h.update(v.to_le_bytes());}}
 format!("{:x}",h.finalize())
}
fn make(k:K,c2:u64,c1:u64,t:u64,ct:u64,cc:u64)->Op {
 let mut o=Op::empty();o.kind=k;o.q_control2=QubitId(c2);o.q_control1=QubitId(c1);o.q_target=QubitId(t);o.c_target=BitId(ct);o.c_condition=BitId(cc);o.validate();o
}
// Full-prefix exact Boolean replay. Fresh opaque atoms only lose information;
// every accepted rewrite uses complete symbolic equality, never fingerprints.
fn global_prefix_simplify(ops:&[Op],cap:usize)->(Vec<Op>,serde_json::Value){global_prefix_simplify_limits(ops,cap,65536)}
fn global_prefix_simplify_limits(ops:&[Op],cap:usize,max_products:usize)->(Vec<Op>,serde_json::Value){
 use std::collections::{BTreeMap,BTreeSet};let no=u64::MAX;let(nq,nb,_,_)=quantum_ecc::circuit::analyze_ops(ops.iter());let(nq,nb)=(nq as usize,nb as usize);let mut alg=Algebra {inner:Expr::default()};let(mut q,mut c)=initial_inputs(ops,nq,nb,&mut alg);let one=1;let zero=0;let mut index:HashMap<E,BTreeSet<usize>>=HashMap::new();for(bit,v)in c.iter().enumerate(){if *v!=0&&*v!=one{index.entry(v.clone()).or_default().insert(bit);}}
 let mut qindex:HashMap<E,BTreeSet<usize>>=HashMap::new();for(wire,&v)in q.iter().enumerate(){if v>1{qindex.entry(v).or_default().insert(wire);}}
 let mut recent=std::collections::VecDeque::<usize>::new();
 let mut base=one.clone();let mut stack=vec![];let mut out=Vec::with_capacity(ops.len());let mut counts=BTreeMap::<&str,usize>::new();
 for(i,o)in ops.iter().enumerate(){if o.kind==K::PushCondition{out.push(*o);stack.push(base.clone());base=alg.and(&base,&c[o.c_condition.0 as usize]);continue;}if o.kind==K::PopCondition{out.push(*o);base=stack.pop().expect("balanced source");continue;}let eff=if o.c_condition.0==no{base.clone()}else{alg.and(&base,&c[o.c_condition.0 as usize])};let t=o.q_target.0 as usize;let a=o.q_control1.0 as usize;let b=o.q_control2.0 as usize;let ct=o.c_target.0 as usize;let mut done=false;
  if o.kind==K::CCX{assert_ne!(t,a);assert_ne!(t,b);let product=alg.and(&q[a],&q[b]);let flip=alg.and(&eff,&product);let fa=alg.and(&eff,&q[a]);let fb=alg.and(&eff,&q[b]);
   if flip==0{*counts.entry("zero_ccx").or_default()+=1;done=true;}
   else if flip==eff{out.push(make(K::X,no,no,o.q_target.0,no,o.c_condition.0));*counts.entry("ccx_to_x").or_default()+=1;done=true;}
   else if flip==fa||flip==fb{let control=if flip==fa{o.q_control1.0}else{o.q_control2.0};out.push(make(K::CX,no,control,o.q_target.0,no,o.c_condition.0));*counts.entry("ccx_to_cx").or_default()+=1;done=true;}
   else{let mut found=None;for(control,other)in[(a,o.q_control2.0),(b,o.q_control1.0)]{if let Some(bits)=index.get(&q[control]){if let Some(&bit)=bits.first(){found=Some((bit,other,false));break;}}let complement=q[control]^1;if let Some(bits)=index.get(&complement){if let Some(&bit)=bits.first(){found=Some((bit,other,true));break;}}}if let Some((bit,other,negative))=found{if negative{out.push(make(K::CX,no,other,o.q_target.0,no,o.c_condition.0));}out.push(make(K::PushCondition,no,no,no,no,bit as u64));out.push(make(K::CX,no,other,o.q_target.0,no,o.c_condition.0));out.push(make(K::PopCondition,no,no,no,no,no));*counts.entry(if negative{"classical_complement"}else{"classical_alias"}).or_default()+=1;done=true;}}
   if !done{let product=alg.and(&q[a],&q[b]);let flip=alg.and(&eff,&product);let guarded_complement=alg.xor(&flip,&eff);let base_product=alg.and(&base,&product);let base_complement=alg.xor(&base_product,&base);for(value,negative)in[(product,false),(product^1,true),(flip,false),(flip^1,true),(guarded_complement,true),(base_product,false),(base_complement,true)]{if value<=1{continue;}if let Some(wires)=qindex.get(&value){if let Some(&wire)=wires.iter().find(|&&wire|wire!=t){if negative{out.push(make(K::X,no,no,o.q_target.0,no,o.c_condition.0));}out.push(make(K::CX,no,wire as u64,o.q_target.0,no,o.c_condition.0));*counts.entry(if negative{"quantum_complement"}else{"quantum_alias"}).or_default()+=1;done=true;break;}}}}
   if !done{let product=alg.and(&q[a],&q[b]);let flip=alg.and(&eff,&product);let base_product=alg.and(&base,&product);'search:for value in[product,flip,base_product]{if value<=1{continue;}for &wire in recent.iter().rev(){if wire==t||q[wire]<=1{continue;}let Some(other_value)=alg.inner.lookup_xor(value,q[wire])else{continue;};for negative in[false,true]{let wanted=other_value^u32::from(negative);if wanted<=1{continue;}if let Some(wires)=qindex.get(&wanted){if let Some(&other)=wires.iter().find(|&&other|other!=t&&other!=wire){if negative{out.push(make(K::X,no,no,o.q_target.0,no,o.c_condition.0));}out.push(make(K::CX,no,wire as u64,o.q_target.0,no,o.c_condition.0));out.push(make(K::CX,no,other as u64,o.q_target.0,no,o.c_condition.0));*counts.entry(if negative{"quantum_pair_complement"}else{"quantum_pair_alias"}).or_default()+=1;done=true;break 'search;}}}}}}
   }else if o.kind==K::CCZ{
   let ab=alg.and(&q[a],&q[b]);let value=alg.and(&ab,&q[t]);let phase=alg.and(&eff,&value);
   if phase==0{*counts.entry("zero_ccz").or_default()+=1;done=true;}
   else if phase==eff{out.push(make(K::Neg,no,no,no,no,o.c_condition.0));*counts.entry("ccz_to_neg").or_default()+=1;done=true;}
   else{
    for wire in[a,b,t]{let v=alg.and(&eff,&q[wire]);if phase==v{out.push(make(K::Z,no,no,wire as u64,no,o.c_condition.0));*counts.entry("ccz_to_z").or_default()+=1;done=true;break;}}
    if !done{for(x,y)in[(a,b),(a,t),(b,t)]{let xy=alg.and(&q[x],&q[y]);let v=alg.and(&eff,&xy);if phase==v{out.push(make(K::CZ,no,x as u64,y as u64,no,o.c_condition.0));*counts.entry("ccz_to_cz").or_default()+=1;done=true;break;}}}
    if !done{let mut found=None;for(control,x,y)in[(a,b,t),(b,a,t),(t,a,b)]{if let Some(bits)=index.get(&q[control]){if let Some(&bit)=bits.first(){found=Some((bit,x,y,false));break;}}let complement=q[control]^1;if let Some(bits)=index.get(&complement){if let Some(&bit)=bits.first(){found=Some((bit,x,y,true));break;}}}if let Some((bit,x,y,negative))=found{if negative{out.push(make(K::CZ,no,x as u64,y as u64,no,o.c_condition.0));}out.push(make(K::PushCondition,no,no,no,no,bit as u64));out.push(make(K::CZ,no,x as u64,y as u64,no,o.c_condition.0));out.push(make(K::PopCondition,no,no,no,no,no));*counts.entry(if negative{"ccz_classical_complement"}else{"ccz_classical_alias"}).or_default()+=1;done=true;}}
   }
  }
  if !done{out.push(*o);}let changed=matches!(o.kind,K::Hmr|K::BitStore0|K::BitStore1|K::BitInvert);if changed&&c[ct]!=0&&c[ct]!=one{let prior=c[ct].clone();if let Some(bits)=index.get_mut(&prior){bits.remove(&ct);if bits.is_empty(){index.remove(&prior);}}}
  let mut affected=vec![];if matches!(o.kind,K::X|K::CX|K::CCX|K::Swap|K::R|K::Hmr){affected.push(t);if o.kind==K::Swap{affected.push(a);}}for &wire in &affected{let value=q[wire];if value>1{let wires=qindex.get_mut(&value).unwrap();assert!(wires.remove(&wire));if wires.is_empty(){qindex.remove(&value);}}}
  match o.kind{K::X=>q[t]=alg.xor(&q[t],&eff),K::CX=>{let v=alg.and(&q[a],&eff);q[t]=alg.xor(&q[t],&v);},K::CCX=>{let v=alg.and(&q[a],&q[b]);let v=alg.and(&v,&eff);q[t]=alg.xor(&q[t],&v);},K::Swap=>{let v=alg.xor(&q[a],&q[t]);let v=alg.and(&v,&eff);q[a]=alg.xor(&q[a],&v);q[t]=alg.xor(&q[t],&v);},K::R|K::Hmr=>{q[t]=alg.select(&q[t],&zero,&eff);if o.kind==K::Hmr{let fresh=alg.fresh();c[ct]=alg.select(&c[ct],&fresh,&eff);}},K::BitInvert=>c[ct]=alg.xor(&c[ct],&eff),K::BitStore0=>c[ct]=alg.select(&c[ct],&zero,&eff),K::BitStore1=>c[ct]=alg.select(&c[ct],&one,&eff),K::Neg|K::Z|K::CZ|K::CCZ|K::Register|K::AppendToRegister|K::DebugPrint=>{},_=>unreachable!()}
  for wire in affected{if q[wire]>1{qindex.entry(q[wire]).or_default().insert(wire);}recent.retain(|&old|old!=wire);recent.push_back(wire);if recent.len()>8{recent.pop_front();}}
  if changed&&c[ct]!=0&&c[ct]!=one{index.entry(c[ct].clone()).or_default().insert(ct);}if i%1000000==0{eprintln!("GLOBAL_PREFIX_PROGRESS op={i} products={} opaque_truncations={} replacements={counts:?}",alg.inner.nodes.len(),0usize);}
 }
 assert!(stack.is_empty());(out,serde_json::json!({"rewrites":counts,"expression_cap":cap,"opaque_truncations":0usize,"forgotten_product_keys":0usize,"exact_product_keys":alg.inner.nodes.len(),"scope":"Full-prefix registered inputs arbitrary/helperszero, every HMR arbitrary. Full-key symbolic equality only; opaque truncations miss proofs only. Original state replay, no random-word or classical mutation changes."}))
}
#[cfg(test)]mod global_prefix_tests{use super::*;use quantum_ecc::circuit::RegisterId;use quantum_ecc::sim::Simulator;use sha3::digest::XofReader;
 struct Words(u8);impl XofReader for Words{fn read(&mut self,out:&mut[u8]){out.fill(self.0);}}
 fn metadata()->Vec<Op>{let mut ops=vec![];for q in 0..4{let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=RegisterId(0);o.q_target=QubitId(q);ops.push(o);}for b in 0..2{let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=RegisterId(1);o.c_target=BitId(b);ops.push(o);}ops}
 fn compare(ops:&[Op],rewritten:&[Op],fault:Option<&[Op]>){for pattern in[0,255,0xa5,0x5a]{let mut ra=Words(pattern);let mut rb=Words(pattern);let mut rf=Words(pattern);let mut a=Simulator::new(6,3,&mut ra);let mut b=Simulator::new(6,3,&mut rb);let mut bad=Simulator::new(6,3,&mut rf);for lane in 0..64{for q in 0..4{a.qubits[q]|=((lane>>q&1)as u64)<<lane;}for bit in 0..2{a.bits[bit]|=((lane>>(bit+4)&1)as u64)<<lane;}}b.qubits.clone_from(&a.qubits);b.bits.clone_from(&a.bits);bad.qubits.clone_from(&a.qubits);bad.bits.clone_from(&a.bits);a.apply_iter(ops.iter());b.apply_iter(rewritten.iter());assert_eq!(a.qubits,b.qubits);assert_eq!(a.bits,b.bits);assert_eq!(a.phase,b.phase);assert!(b.stats.toffoli_gates<=a.stats.toffoli_gates);if let Some(fault)=fault{bad.apply_iter(fault.iter());assert!(a.qubits!=bad.qubits||a.phase!=bad.phase);}}}
 #[test]fn global_zero_and_linear_controls_preserve_all_basis_phase_values_and_count(){let n=u64::MAX;let mut ops=metadata();ops.extend([make(K::CCX,0,4,2,n,n),make(K::CCZ,0,4,1,n,n),make(K::X,n,n,4,n,n),make(K::CCX,0,4,2,n,0),make(K::X,n,n,4,n,n)]);let(out,s)=global_prefix_simplify(&ops,1024);assert_eq!(s["rewrites"]["zero_ccx"],1);assert_eq!(s["rewrites"]["zero_ccz"],1);assert_eq!(s["rewrites"]["ccx_to_cx"],1);compare(&ops,&out,None);}
 #[test]fn global_classical_alias_complement_and_fresh_measurement_keep_guards_phase_and_rng(){let n=u64::MAX;for mutate in[false,true]{let mut ops=metadata();ops.push(make(K::Hmr,n,n,5,2,n));ops.push(make(K::X,n,n,4,n,2));if mutate{ops.push(make(K::BitInvert,n,n,n,2,n));}ops.push(make(K::CCX,0,4,2,n,0));if mutate{ops.push(make(K::BitInvert,n,n,n,2,n));}ops.push(make(K::X,n,n,4,n,2));let(out,s)=global_prefix_simplify(&ops,1024);assert_eq!(s["rewrites"][if mutate{"classical_complement"}else{"classical_alias"}],1);compare(&ops,&out,None);}}
 #[test]fn registered_input_declared_late_is_never_assumed_zero(){let n=u64::MAX;let mut ops=metadata();ops.push(make(K::CCX,0,4,2,n,n));let mut declared=Op::empty();declared.kind=K::AppendToRegister;declared.q_target=QubitId(4);declared.r_target=RegisterId(0);ops.push(declared);let(out,s)=global_prefix_simplify(&ops,1024);assert_eq!(out.len(),ops.len());assert!(s["rewrites"].as_object().unwrap().is_empty());}
 #[test]fn opaque_limits_stay_sound_and_missing_classical_guard_is_detected(){let n=u64::MAX;let mut ops=metadata();ops.extend([make(K::X,n,n,4,n,0),make(K::CCX,1,4,2,n,1)]);let(out,s)=global_prefix_simplify(&ops,1);assert_eq!(s["rewrites"]["classical_alias"],1);let bad:Vec<_>=out.iter().filter(|o|!matches!(o.kind,K::PushCondition|K::PopCondition)).copied().collect();compare(&ops,&out,Some(&bad));}
 #[test]fn forgetting_product_keys_only_loses_precision_and_preserves_full_protected_semantics(){let n=u64::MAX;let mut seed=0xa8d7135f23649b01u64;for _ in 0..12{let mut ops=metadata();for step in 0..80{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);let t=(seed>>8)%6;let a=(t+1+(seed>>16)%5)%6;let b=(0..6).find(|&x|x!=a&&x!=t).unwrap();let condition=if seed&8!=0{n}else{(seed>>24)%3};ops.push(match seed%6{0=>make(K::X,n,n,t,n,condition),1=>make(K::CX,n,a,t,n,condition),2=>make(K::CCX,b,a,t,n,condition),3=>make(K::CCZ,b,a,t,n,condition),4=>make(K::Swap,n,a,t,n,condition),_=>make(K::BitInvert,n,n,n,(seed>>32)%3,condition)});if step%16==0{ops.push(make(K::Hmr,n,n,5,2,condition));}}let(out,s)=global_prefix_simplify_limits(&ops,3,1);assert!(s["exact_product_keys"].as_u64().unwrap()>0);compare(&ops,&out,None);}}

 #[test]fn phase_lowerings_keep_absolute_phase_and_all_original_guards(){let n=u64::MAX;
  let mut ops=metadata();ops.extend([make(K::X,n,n,4,n,n),make(K::X,n,n,5,n,n),make(K::PushCondition,n,n,n,n,0),make(K::CCZ,4,5,0,n,1),make(K::PopCondition,n,n,n,n,n)]);let(out,s)=global_prefix_simplify(&ops,1024);assert_eq!(s["rewrites"]["ccz_to_z"],1);compare(&ops,&out,None);
  let mut ops=metadata();ops.extend([make(K::X,n,n,4,n,n),make(K::CCZ,0,4,1,n,1)]);let(out,s)=global_prefix_simplify(&ops,1024);assert_eq!(s["rewrites"]["ccz_to_cz"],1);compare(&ops,&out,None);
  let mut ops=metadata();ops.extend([make(K::X,n,n,4,n,n),make(K::X,n,n,5,n,n),make(K::R,n,n,0,n,n),make(K::X,n,n,0,n,n),make(K::CCZ,4,5,0,n,1)]);let(out,s)=global_prefix_simplify(&ops,1024);assert_eq!(s["rewrites"]["ccz_to_neg"],1);let bad:Vec<_>=out.iter().filter(|o|o.kind!=K::Neg).copied().collect();compare(&ops,&out,Some(&bad));
 }
 #[test]fn phase_product_relation_can_remove_one_t_without_sampling(){let n=u64::MAX;let mut ops=metadata();ops.extend([make(K::CCX,0,1,4,n,n),make(K::CCZ,0,1,4,n,0)]);let(out,s)=global_prefix_simplify(&ops,1024);assert_eq!(s["rewrites"]["ccz_to_z"],1);compare(&ops,&out,None);}
 #[test]fn phase_classical_alias_complement_and_mutation_preserve_rng_and_phase(){let n=u64::MAX;for target in[0,1,4]{for mutate in[false,true]{let mut ops=metadata();ops.extend([make(K::Hmr,n,n,5,2,n),make(K::X,n,n,4,n,2)]);if mutate{ops.push(make(K::BitInvert,n,n,n,2,n));}ops.push(match target{0=>make(K::CCZ,4,0,1,n,0),1=>make(K::CCZ,0,4,1,n,0),_=>make(K::CCZ,0,1,4,n,0)});let(out,s)=global_prefix_simplify(&ops,1024);assert_eq!(s["rewrites"][if mutate{"ccz_classical_complement"}else{"ccz_classical_alias"}],1);compare(&ops,&out,None);}}}
 #[test]fn independent_registered_phase_controls_are_not_lowered(){let n=u64::MAX;let mut ops=metadata();ops.extend([make(K::CCZ,0,1,2,n,n),make(K::CCZ,0,1,2,n,0)]);let(out,s)=global_prefix_simplify(&ops,1024);assert!(s["rewrites"].as_object().unwrap().is_empty());assert_eq!(hash(&ops),hash(&out));compare(&ops,&out,None);}

}

fn main(){let args:Vec<_>=std::env::args().collect();assert_eq!(args.len(),3);let ops=io::load_ops(&args[1]);let(out,stats)=global_prefix_simplify(&ops,1024);let result=serde_json::json!({"status":"GLOBAL_FULL_PREFIX_COMPONENT_PROOFS_COMPLETE_NOT_SCORED","input_records_sha3":hash(&ops),"output_records_sha3":hash(&out),"input_count":ops.len(),"output_count":out.len(),"proof":stats});std::fs::write(format!("{}.json",args[2]),serde_json::to_string_pretty(&result).unwrap()+"\n").unwrap();io::save_ops(&format!("{}.ops.bin",args[2]),&out);println!("{result}");}

#[cfg(test)]mod semantic_algebra_controls{use super::*;
 #[test]fn distributivity_and_unused_support_are_exact(){let mut e=Expr::default();let a=e.atom();let b=e.atom();let ab=e.and(a,b);let anb=e.and(a,b^1);assert_eq!(e.xor(ab,anb),a);let or=e.or(a,b);assert_eq!(e.and(or,a),a);assert_ne!(or,a);}
 #[test]fn above_six_atom_cofactor_has_disabled_negative_control(){fn run(enabled:bool)->(u32,u32){let mut e=Expr::default();e.restricting=!enabled;let mut g=1;let mut old=1;for _ in 0..6{let a=e.atom();g=e.and(g,a);let b=e.atom();old=e.and(old,b);}assert_eq!(e.semantic(g).atoms.len(),6);assert_eq!(e.semantic(old).atoms.len(),6);let r=e.atom();let v=e.ite(g,r,old);let actual=e.and(g,v);let expected=e.and(g,r);(actual,expected)}let no=run(false);assert_ne!(no.0,no.1);let yes=run(true);assert_eq!(yes.0,yes.1);}
 #[test]fn complete_six_atom_expression_truths_match_original_functions(){fn get(e:&Expr,v:u32,assignment:usize,atoms:&[u32])->bool{if v<=1{return v==1;}let(k,a,b)=e.nodes[(v/2-1)as usize];let value=match k{0=>assignment>>atoms.iter().position(|&a|a==v&!1).unwrap()&1!=0,1=>get(e,a,assignment,atoms)&get(e,b,assignment,atoms),_=>get(e,a,assignment,atoms)^get(e,b,assignment,atoms)};value^(v&1!=0)}let mut e=Expr::default();let atoms:Vec<_>=(0..6).map(|_|e.atom()).collect();let mut pool=atoms.clone();let mut seed=0xa8d7135f23649b01u64;for _ in 0..500{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);let(a,b,g)=(pool[seed as usize%pool.len()],pool[(seed>>17)as usize%pool.len()],pool[(seed>>33)as usize%pool.len()]);let kind=seed%3;let v=match kind{0=>e.and(a,b),1=>e.xor(a,b),_=>e.ite(g,a,b)};for assignment in 0..64{let(a,b,g)=(get(&e,a,assignment,&atoms),get(&e,b,assignment,&atoms),get(&e,g,assignment,&atoms));let want=match kind{0=>a&b,1=>a^b,_=>if g{a}else{b}};assert_eq!(get(&e,v,assignment,&atoms),want);}pool.push(v);if pool.len()>64{pool.remove(6);}}}
}

#[cfg(test)]mod quantum_alias_tests{
 use super::*;use quantum_ecc::circuit::RegisterId;use quantum_ecc::sim::Simulator;use sha3::digest::XofReader;
 struct Words(u8);impl XofReader for Words{fn read(&mut self,b:&mut[u8]){b.fill(self.0);}}
 fn metadata()->Vec<Op>{let mut ops=vec![];for q in 0..4{let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=RegisterId(0);o.q_target=QubitId(q);ops.push(o);}for b in 0..2{let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=RegisterId(1);o.c_target=BitId(b);ops.push(o);}ops}
 fn check(ops:&[Op],out:&[Op]){for pattern in[0,255,0xa5,0x5a]{let(mut ra,mut rb)=(Words(pattern),Words(pattern));let(mut a,mut b)=(Simulator::new(6,3,&mut ra),Simulator::new(6,3,&mut rb));for lane in 0..64{for q in 0..4{a.qubits[q]|=((lane>>q&1)as u64)<<lane;}for bit in 0..2{a.bits[bit]|=((lane>>(bit+4)&1)as u64)<<lane;}}b.qubits.clone_from(&a.qubits);b.bits.clone_from(&a.bits);a.apply_iter(ops.iter());b.apply_iter(out.iter());assert_eq!(a.qubits,b.qubits);assert_eq!(a.bits,b.bits);assert_eq!(a.phase,b.phase);assert!(a.stats.toffoli_gates>=b.stats.toffoli_gates);}}
 #[test]fn retained_quantum_product_and_complement_copy_keep_phase_and_guards(){let n=u64::MAX;for neg in[false,true]{for guarded in[false,true]{let mut ops=metadata();if guarded{ops.push(make(K::PushCondition,n,n,n,n,0));}ops.push(make(K::CCX,0,1,4,n,n));if neg{ops.push(make(K::X,n,n,4,n,n));}ops.push(make(K::CCX,0,1,2,n,1));ops.push(make(K::CCZ,0,2,3,n,0));if guarded{ops.push(make(K::PopCondition,n,n,n,n,n));}let(out,s)=global_prefix_simplify(&ops,1024);assert_eq!(s["rewrites"][if neg{"quantum_complement"}else{"quantum_alias"}],1);check(&ops,&out);}}}
 #[test]fn target_self_alias_and_stale_quantum_copy_are_never_used(){let n=u64::MAX;let mut ops=metadata();ops.extend([make(K::CCX,0,1,4,n,n),make(K::R,n,n,4,n,n),make(K::CCX,0,1,2,n,n),make(K::CCX,0,1,2,n,n)]);let(out,s)=global_prefix_simplify(&ops,1024);assert!(s["rewrites"].get("quantum_alias").is_none());check(&ops,&out);}
 #[test]fn quantum_copy_matches_effective_guard_after_classical_mutation(){let n=u64::MAX;let mut ops=metadata();ops.extend([make(K::CCX,0,1,4,n,0),make(K::BitInvert,n,n,n,0,n),make(K::BitInvert,n,n,n,0,n),make(K::CCX,0,1,2,n,0),make(K::Hmr,n,n,4,2,n),make(K::CZ,n,0,1,n,2)]);let(out,s)=global_prefix_simplify(&ops,1024);assert_eq!(s["rewrites"]["quantum_alias"],1);check(&ops,&out);}
}

#[cfg(test)]mod quantum_pair_tests{
 use super::*;use quantum_ecc::circuit::RegisterId;use quantum_ecc::sim::Simulator;use sha3::digest::XofReader;
 struct Words(u8);impl XofReader for Words{fn read(&mut self,b:&mut[u8]){b.fill(self.0);}}
 fn metadata()->Vec<Op>{let mut ops=vec![];for q in 0..4{let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=RegisterId(0);o.q_target=QubitId(q);ops.push(o);}for b in 0..2{let mut o=Op::empty();o.kind=K::AppendToRegister;o.r_target=RegisterId(1);o.c_target=BitId(b);ops.push(o);}ops}
 fn check(ops:&[Op],out:&[Op]){for pattern in[0,255,0xa5,0x5a]{let(mut ra,mut rb)=(Words(pattern),Words(pattern));let(mut a,mut b)=(Simulator::new(6,3,&mut ra),Simulator::new(6,3,&mut rb));for lane in 0..64{for q in 0..4{a.qubits[q]|=((lane>>q&1)as u64)<<lane;}for bit in 0..2{a.bits[bit]|=((lane>>(bit+4)&1)as u64)<<lane;}}b.qubits.clone_from(&a.qubits);b.bits.clone_from(&a.bits);a.apply_iter(ops.iter());b.apply_iter(out.iter());assert_eq!(a.qubits,b.qubits);assert_eq!(a.bits,b.bits);assert_eq!(a.phase,b.phase);assert!(a.stats.toffoli_gates>=b.stats.toffoli_gates);}}
 #[test]fn xor_of_retained_old_and_updated_target_reuses_product_with_no_new_rng(){let n=u64::MAX;for neg in[false,true]{for guarded in[false,true]{let mut ops=metadata();ops.push(make(K::CX,n,2,4,n,n));if guarded{ops.push(make(K::PushCondition,n,n,n,n,0));}ops.push(make(K::CCX,0,1,2,n,1));if neg{ops.push(make(K::X,n,n,2,n,n));}ops.push(make(K::CCX,0,1,3,n,1));if guarded{ops.push(make(K::PopCondition,n,n,n,n,n));}let(out,s)=global_prefix_simplify(&ops,1024);assert_eq!(s["rewrites"][if neg{"quantum_pair_complement"}else{"quantum_pair_alias"}],1,"neg={neg} guarded={guarded} {s}");check(&ops,&out);}}}
 #[test]fn reset_or_mutated_pair_carrier_never_supplies_a_stale_copy(){let n=u64::MAX;let mut ops=metadata();ops.extend([make(K::CX,n,2,4,n,n),make(K::CCX,0,1,2,n,n),make(K::R,n,n,4,n,n),make(K::CCX,0,1,3,n,n)]);let(out,s)=global_prefix_simplify(&ops,1024);assert!(s["rewrites"].get("quantum_pair_alias").is_none());check(&ops,&out);}
 #[test]fn lookup_only_xor_preserves_exact_truths_and_never_allocates_unknown_queries(){let mut e=Expr::default();let a=e.atom();let b=e.atom();let c=e.atom();let ab=e.xor(a,b);let abc=e.xor(ab,c);let before=e.nodes.len();assert_eq!(e.lookup_xor(ab,c),Some(abc));assert_eq!(e.lookup_xor(ab^1,c),Some(abc^1));assert_eq!(e.lookup_xor(abc,ab),Some(c));let fresh=e.atom();let before_fresh=e.nodes.len();assert_eq!(e.lookup_xor(fresh,abc),None);assert_eq!(e.nodes.len(),before_fresh);assert_eq!(before_fresh,before+1);}
}
